import sys
from collections import defaultdict, deque

def min_coprocessor_calls(N, M, E, dependencies):
    # Build the graph
    graph = defaultdict(list)
    in_degree = [0] * N
    for T1, T2 in dependencies:
        graph[T2].append(T1)
        in_degree[T1] += 1

    # Initialize the queue for tasks that can be executed immediately
    queue = deque()
    for i in range(N):
        if in_degree[i] == 0:
            queue.append(i)

    # Count the number of coprocessor calls
    coprocessor_calls = 0
    while queue:
        size = len(queue)
        current_level = []

        for _ in range(size):
            task = queue.popleft()
            if E[task] == 1:
                current_level.append(task)
            else:
                # Execute main processor task immediately
                for neighbor in graph[task]:
                    in_degree[neighbor] -= 1
                    if in_degree[neighbor] == 0:
                        queue.append(neighbor)

        # If there are any coprocessor tasks in the current level, make a coprocessor call
        if current_level:
            coprocessor_calls += 1
            for task in current_level:
                for neighbor in graph[task]:
                    in_degree[neighbor] -= 1
                    if in_degree[neighbor] == 0:
                        queue.extend([neighbor])

    return coprocessor_calls

# Read input
